package com.neu.CoursePlatform.controller;
import com.neu.CoursePlatform.agentic.*; import com.neu.CoursePlatform.common.Auth; import com.neu.CoursePlatform.common.Result; import com.neu.CoursePlatform.entity.KnowledgePoint; import com.neu.CoursePlatform.service.KnowledgePointService; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.Map;
@RestController @RequestMapping("/api/ability-map") public class AbilityMapGenerationController { private final AgenticClient agent; private final KnowledgePointService points; private final Auth auth; public AbilityMapGenerationController(AgenticClient agent,KnowledgePointService points,Auth auth){this.agent=agent;this.points=points;this.auth=auth;} @PostMapping("/generate") public Result<AgenticResponse> generate(@RequestParam String courseCode,HttpSession session){if(!auth.canModifyCourse(session,courseCode))return Result.fail("无权限");List<KnowledgePoint> knowledgePoints=points.listByCourseCode(courseCode,null);AgenticRequest request=new AgenticRequest();request.setCourseCode(courseCode);request.setContext(Map.of("knowledgePoints",knowledgePoints));AgenticResponse response=agent.invoke("ability-map",request);return response.isSuccess()?Result.ok(response):Result.serviceUnavailable("AI 服务暂不可用");} }
